package com.sumedha.commerce.auth.security; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class OpaqueTokenServiceTest { @Test void generatesDistinctHighEntropyTokens(){OpaqueTokenService s=new OpaqueTokenService();String first=s.generate(),second=s.generate();assertFalse(first.isBlank());assertTrue(first.length()>=64);assertNotEquals(first,second);} @Test void digestIsStableOpaqueAndDistinct(){OpaqueTokenService s=new OpaqueTokenService();String first="first-token",second="second-token";String digest=s.hash(first);assertNotEquals(first,digest);assertEquals(digest,s.hash(first));assertNotEquals(digest,s.hash(second));assertFalse(digest.contains(first));}}
